#!/usr/bin/env bash
set -eo pipefail
source /data1/home/sunyiq/miniconda3/etc/profile.d/conda.sh
conda activate nh_final
set -u
export PYTHONDONTWRITEBYTECODE=1
export OMP_NUM_THREADS=4
export OPENBLAS_NUM_THREADS=4
python -B - <<'DEPLOY_READONLY_LSTM'
import base64,json,zlib
from pathlib import Path
root=Path('/data1/home/sunyiq/zhenjiang_fixed200_003_lstm_dev100_20261022_001')
root.mkdir(exist_ok=True)
(root/'logs').mkdir(exist_ok=True)
files=json.loads(zlib.decompress(base64.b64decode('')))
for name,value in files.items():
 path=root/name
 raw=base64.b64decode(value)
 if path.exists():
  if path.read_bytes()!=raw:raise ValueError('existing diagnostic package differs: '+name)
 else:
  with path.open('xb') as handle:handle.write(raw)
DEPLOY_READONLY_LSTM
